// src/utils/pharmacyHelpers.ts
function getUnitsPerPack(med) {
	return med.unitsPerPack > 0 ? med.unitsPerPack : 1;
}
function getPieceUnitName(dosageForm) {
	switch (dosageForm) {
		case "Tablet": return "Tab";
		case "Capsule": return "Cap";
		case "Syrup":
		case "Suspension": return "Btl";
		case "Injection": return "Amp";
		case "Drops": return "Drp";
		case "Ointment":
		case "Cream": return "Tube";
		case "Inhaler": return "Inh";
		case "Sachet": return "Sach";
		case "Patch": return "Ptc";
		case "Infusion": return "Bag";
		default: return "Pcs";
	}
}
function getPieceRetailPrice(med) {
	if (med.looseRetailPrice && med.looseRetailPrice > 0) return med.looseRetailPrice;
	const units = getUnitsPerPack(med);
	return Number((med.unitRetailPrice / units).toFixed(2));
}
function getPieceCostPrice(med) {
	if (med.looseCostPrice && med.looseCostPrice > 0) return med.looseCostPrice;
	const units = getUnitsPerPack(med);
	return Number((med.unitCostPrice / units).toFixed(2));
}
function getTotalPiecesInStock(med) {
	const units = getUnitsPerPack(med);
	return med.currentStockPacks * units + (med.currentStockLoose || 0);
}
function formatPKR(amount) {
	return `Rs. ${Math.round(amount).toLocaleString("en-PK")}`;
}
function getDaysUntilExpiry(expiryDateStr) {
	if (!expiryDateStr) return 999;
	const expiry = new Date(expiryDateStr);
	if (isNaN(expiry.getTime())) return 999;
	const now = /* @__PURE__ */ new Date();
	expiry.setHours(0, 0, 0, 0);
	now.setHours(0, 0, 0, 0);
	const diffTime = expiry.getTime() - now.getTime();
	return Math.ceil(diffTime / 864e5);
}
function isExpired(expiryDateStr) {
	return getDaysUntilExpiry(expiryDateStr) <= 0;
}
function isExpiringSoon(expiryDateStr, thresholdDays = 90) {
	const days = getDaysUntilExpiry(expiryDateStr);
	return days > 0 && days <= thresholdDays;
}
function getExpiryWindow(expiryDateStr) {
	const days = getDaysUntilExpiry(expiryDateStr);
	if (days <= 0) return "expired";
	if (days <= 30) return "30_days";
	if (days <= 60) return "60_days";
	if (days <= 90) return "90_days";
	return "safe";
}
function getExpiryBadgeMeta(expiryDateStr) {
	const days = getDaysUntilExpiry(expiryDateStr);
	const window = getExpiryWindow(expiryDateStr);
	if (window === "expired") return {
		window,
		days,
		shortLabel: days === 0 ? "Expires Today" : `Expired ${Math.abs(days)}d ago`,
		horizonLabel: "EXPIRED",
		badgeClass: "bg-rose-100 text-rose-800 border border-rose-300",
		textClass: "text-rose-600 font-bold"
	};
	if (window === "30_days") return {
		window,
		days,
		shortLabel: `${days}d left`,
		horizonLabel: "≤ 30 Days",
		badgeClass: "bg-rose-100 text-rose-800 border border-rose-200",
		textClass: "text-rose-600 font-bold"
	};
	if (window === "60_days") return {
		window,
		days,
		shortLabel: `${days}d left`,
		horizonLabel: "≤ 60 Days",
		badgeClass: "bg-amber-100 text-amber-800 border border-amber-200",
		textClass: "text-amber-600 font-semibold"
	};
	if (window === "90_days") return {
		window,
		days,
		shortLabel: `${days}d left`,
		horizonLabel: "≤ 90 Days",
		badgeClass: "bg-sky-100 text-sky-800 border border-sky-200",
		textClass: "text-sky-700 font-semibold"
	};
	return {
		window,
		days,
		shortLabel: `${days}d`,
		horizonLabel: "Safe (>90d)",
		badgeClass: "bg-emerald-50 text-emerald-700 border border-emerald-200",
		textClass: "text-slate-600"
	};
}
